#include <stereoforge/daxa_dual_preprocess.hpp>
#include <daxa/utils/task_graph.hpp>
#include <daxa/c/device.h>
#include <cstring>
#include <fstream>
#include <thread>
namespace stereoforge {
namespace {
void require(bool ok,const char* msg){if(!ok)throw std::invalid_argument(msg);}
struct Parameters {uint64_t raw;std::array<uint64_t,2> original,rectified,luma,support;std::array<uint64_t,4> maps;uint32_t eye_width,source_height,stride,width,height;};
static_assert(sizeof(Parameters)==128);
struct Push {uint64_t parameters;};
std::vector<uint32_t> shader(const char* name){std::ifstream f(std::filesystem::path(SF_DAXA_PREPROCESS_SPIRV_DIRECTORY)/(std::string("daxa-preprocess-")+name+".spv"),std::ios::binary|std::ios::ate);require(bool(f),"preprocess shader missing");auto size=f.tellg();require(size>0&&size%4==0,"invalid preprocess shader");std::vector<uint32_t> words(size_t(size)/4);f.seekg(0);f.read(reinterpret_cast<char*>(words.data()),size);require(bool(f),"shader read failed");return words;}
}
struct DaxaDualPreprocess::Impl: detail::DaxaFrameOwner {
    struct Resources {std::shared_ptr<DaxaFoundation> context;std::vector<daxa::BufferId> buffers;std::vector<daxa::MemoryBlock> memory;~Resources(){if(!context)return;auto& d=context->device;try{d.wait_idle();for(auto b:buffers)if(d.is_id_valid(b))d.destroy_buffer(b);d.collect_garbage();}catch(...){} }} resources;
    struct Slot {std::shared_ptr<detail::DaxaFrameSlot> full=std::make_shared<detail::DaxaFrameSlot>(),coarse=std::make_shared<detail::DaxaFrameSlot>();daxa::BufferId staging,raw;std::array<daxa::BufferId,2> params;std::vector<daxa::ExternalTaskBuffer> nodes;std::unique_ptr<daxa::TaskGraph> graph;uint64_t submit=0;};
    std::shared_ptr<const DaxaRectification> full,coarse;std::vector<std::shared_ptr<Slot>> slots;std::array<daxa::ComputePipeline,2> pipelines;uint64_t next_generation=1, storage_limit=0;const std::thread::id thread=std::this_thread::get_id();
    void check_thread()const{require(thread==std::this_thread::get_id(),"dual producer requires one submission thread");}
    daxa::BufferId alloc(size_t n,const std::string& name,bool host=false){require(n&&n<=storage_limit,"dual producer buffer exceeds storage range");auto& d=context->device;daxa::BufferInfo info{.size=n,.name=name};daxa::BufferId id;if(host){auto mem=d.create_memory({.requirements=context->coherent_readback_requirements(info),.flags=daxa::MemoryFlagBits::HOST_ACCESS_RANDOM});id=d.create_buffer_from_memory_block({.buffer_info=info,.memory_block=mem});resources.memory.push_back(std::move(mem));}else id=d.create_buffer(info);resources.buffers.push_back(id);return id;}
    bool available(const std::shared_ptr<Slot>& s,uint64_t oldest)const{return s->full.use_count()==1&&s->coarse.use_count()==1&&detail::completed_submission(s->submit,oldest);}
    size_t collect_at(uint64_t oldest){size_t n=0;for(auto& s:slots)if(available(s,oldest)&&s->full->source){s->full->source.reset();s->coarse->source.reset();++n;}return n;}
    ~Impl(){if(context){try{context->device.wait_idle();}catch(...){}}slots.clear();pipelines={};}
    Impl(DaxaRectification f,DaxaRectification c,unsigned count,std::shared_ptr<DaxaFoundation> foundation){
        require(foundation&&foundation->device.get(),"dual producer requires foundation");require(count==2,"dual producer requires two slots");f.validate(count);c.validate(count);require(f.requested_bytes(count)+c.requested_bytes(count)<2ull*1024*1024*1024,"dual producer allocation ceiling exceeded");require(f.eye_width==c.eye_width&&f.source_height==c.source_height&&f.stride_bytes==c.stride_bytes&&f.original_identity==c.original_identity,"dual source geometry mismatch");
        context=std::move(foundation);resources.context=context;resources.buffers.reserve(64);resources.memory.reserve(16);slots.reserve(count);full=std::make_shared<const DaxaRectification>(std::move(f));coarse=std::make_shared<const DaxaRectification>(std::move(c));auto& d=context->device;auto physical=daxa_dvc_get_vk_physical_device(d.get());VkPhysicalDeviceProperties props{};vkGetPhysicalDeviceProperties(physical,&props);storage_limit=props.limits.maxStorageBufferRange;require(props.limits.maxComputeWorkGroupInvocations>=64&&props.limits.maxComputeWorkGroupSize[0]>=8&&props.limits.maxComputeWorkGroupSize[1]>=8,"dual producer workgroups unsupported");for(auto shape:{std::array<uint32_t,2>{full->eye_width,full->source_height},std::array<uint32_t,2>{full->width,full->height},std::array<uint32_t,2>{coarse->width,coarse->height}})require((shape[0]+7)/8<=props.limits.maxComputeWorkGroupCount[0]&&(shape[1]+7)/8<=props.limits.maxComputeWorkGroupCount[1]&&props.limits.maxComputeWorkGroupCount[2]>=2,"dual producer dispatch limit");
        for(unsigned i=0;i<2;++i){auto words=shader(i?"rectify_gray":"decode_yuyv");pipelines[i]=d.create_compute_pipeline({.shader_info={.byte_code=words.data(),.byte_code_size=uint32_t(words.size())},.push_constant_size=sizeof(Push),.name=i?"dual_rectify":"dual_decode"});}
        std::array<std::array<daxa::BufferId,4>,2> maps;auto recorder=d.create_command_recorder({.name="dual map setup"});recorder.pipeline_barrier({.src_access=daxa::AccessConsts::HOST_WRITE,.dst_access=daxa::AccessConsts::TRANSFER_READ});for(unsigned grid=0;grid<2;++grid){auto& cfg=grid?*coarse:*full;for(unsigned j=0;j<4;++j){auto n=cfg.maps[j].size()*4;maps[grid][j]=alloc(n,"dual_map");auto st=alloc(n,"dual_map_staging",true);std::memcpy(d.buffer_host_address(st).value(),cfg.maps[j].data(),n);recorder.copy_buffer_to_buffer({.src_buffer=st,.dst_buffer=maps[grid][j],.size=n});}}recorder.pipeline_barrier({.src_access=daxa::AccessConsts::TRANSFER_WRITE,.dst_access=daxa::AccessConsts::COMPUTE_SHADER_READ});auto command=recorder.complete_current_commands();d.submit_commands({.command_lists={&command,1}});d.wait_idle();
        for(unsigned index=0;index<count;++index){auto s=std::make_shared<Slot>();s->full->calibration=full;s->coarse->calibration=coarse;auto raw_bytes=(uint64_t(full->stride_bytes)*full->source_height+3)&~uint64_t{3};s->staging=alloc(raw_bytes,"dual_staging",true);s->raw=alloc(raw_bytes,"dual_yuyv");for(unsigned p=0;p<8;++p){auto n=uint64_t(p<2?full->eye_width:full->width)*(p<2?full->source_height:full->height)*4;s->full->planes[p]=alloc(n,"dual_full");}for(unsigned p=0;p<2;++p)s->coarse->planes[p]=s->full->planes[p];for(unsigned p=2;p<8;++p)s->coarse->planes[p]=alloc(uint64_t(coarse->width)*coarse->height*4,"dual_coarse");
            std::array<uint64_t,2> addresses{};for(unsigned grid=0;grid<2;++grid){auto& cfg=grid?*coarse:*full;auto child=grid?s->coarse:s->full;Parameters p{};p.raw=d.device_address(s->raw).value();for(unsigned eye=0;eye<2;++eye){p.original[eye]=d.device_address(child->planes[eye]).value();p.rectified[eye]=d.device_address(child->planes[2+eye]).value();p.luma[eye]=d.device_address(child->planes[4+eye]).value();p.support[eye]=d.device_address(child->planes[6+eye]).value();}for(unsigned j=0;j<4;++j)p.maps[j]=d.device_address(maps[grid][j]).value();p.eye_width=cfg.eye_width;p.source_height=cfg.source_height;p.stride=cfg.stride_bytes;p.width=cfg.width;p.height=cfg.height;s->params[grid]=alloc(sizeof(p),"dual_params",true);std::memcpy(d.buffer_host_address(s->params[grid]).value(),&p,sizeof(p));addresses[grid]=d.device_address(s->params[grid]).value();}
            s->graph=std::make_unique<daxa::TaskGraph>(daxa::TaskGraphInfo{.device=d,.name="dual_preprocess"});auto& graph=*s->graph;std::vector<daxa::BufferId> ids{s->staging,s->raw,s->params[0],s->params[1]};for(auto id:s->full->planes)ids.push_back(id);for(unsigned p=2;p<8;++p)ids.push_back(s->coarse->planes[p]);for(auto const& grid:maps)for(auto id:grid)ids.push_back(id);s->nodes.reserve(ids.size());std::vector<daxa::TaskBufferView> v;v.reserve(ids.size());for(unsigned resource=0;resource<ids.size();++resource){auto name="dual_"+std::to_string(index)+"_resource_"+std::to_string(resource);s->nodes.emplace_back(daxa::ExternalTaskBuffer({.buffer=ids[resource],.name=name}));v.push_back(graph.register_buffer(s->nodes.back()));}
            graph.add_task(daxa::InlineTask::Transfer("dual host staging").host.writes(v[0]).executes([](daxa::TaskInterface){}));
            graph.add_task(daxa::InlineTask::Transfer("dual source upload").reads(v[0]).writes(v[1]).executes([src=v[0],dst=v[1],raw_bytes](daxa::TaskInterface ti){ti.recorder.pipeline_barrier({.src_access=daxa::AccessConsts::TRANSFER_WRITE|daxa::AccessConsts::COMPUTE_SHADER_READ,.dst_access=daxa::AccessConsts::TRANSFER_WRITE});ti.recorder.copy_buffer_to_buffer({.src_buffer=ti.get(src).id,.dst_buffer=ti.get(dst).id,.size=raw_bytes});}));
            graph.add_task(daxa::InlineTask::Compute("dual decode").reads(v[1],v[2]).writes(v[4],v[5]).executes([this,addresses](daxa::TaskInterface ti){ti.recorder.pipeline_barrier({.src_access=daxa::AccessConsts::COMPUTE_SHADER_READ|daxa::AccessConsts::COMPUTE_SHADER_WRITE,.dst_access=daxa::AccessConsts::COMPUTE_SHADER_WRITE});ti.recorder.set_pipeline(pipelines[0]);ti.recorder.push_constant(Push{addresses[0]});ti.recorder.dispatch({(full->eye_width+7)/8,(full->source_height+7)/8,2});}));
            graph.add_task(daxa::InlineTask::Compute("dual full rectify").reads(v[2],v[4],v[5],v[18],v[19],v[20],v[21]).writes(v[6],v[7],v[8],v[9],v[10],v[11]).executes([this,addresses](daxa::TaskInterface ti){ti.recorder.set_pipeline(pipelines[1]);ti.recorder.push_constant(Push{addresses[0]});ti.recorder.dispatch({(full->width+7)/8,(full->height+7)/8,2});}));
            graph.add_task(daxa::InlineTask::Compute("dual coarse rectify").reads(v[3],v[4],v[5],v[22],v[23],v[24],v[25]).writes(v[12],v[13],v[14],v[15],v[16],v[17]).executes([this,addresses](daxa::TaskInterface ti){ti.recorder.set_pipeline(pipelines[1]);ti.recorder.push_constant(Push{addresses[1]});ti.recorder.dispatch({(coarse->width+7)/8,(coarse->height+7)/8,2});}));graph.submit({});graph.complete({});slots.push_back(std::move(s));
        }
    }
};
DaxaDualPreprocess::DaxaDualPreprocess(DaxaRectification f,DaxaRectification c,unsigned slots,std::shared_ptr<DaxaFoundation> context):impl_(std::make_shared<Impl>(std::move(f),std::move(c),slots,std::move(context))){}
DaxaDualPreprocess::Frame DaxaDualPreprocess::enqueue(CaptureLease source){auto& e=*impl_;e.check_thread();e.context->device.collect_garbage();require(bool(source),"dual source required");e.full->validate_source(*source);e.coarse->validate_source(*source);auto oldest=e.context->device.oldest_pending_submit_index();e.collect_at(oldest);for(auto& slot:e.slots)if(e.available(slot,oldest)){slot->full->source=source;slot->coarse->source=source;slot->full->generation=slot->coarse->generation=e.next_generation++;auto* target=reinterpret_cast<uint8_t*>(e.context->device.buffer_host_address(slot->staging).value());auto bytes=source->packed_yuyv.size();std::memcpy(target,source->packed_yuyv.data(),bytes);std::memset(target+bytes,0,(4-(bytes&3))&3);try{slot->graph->execute({});}catch(...){slot->submit=e.context->device.latest_queue_submit_index(daxa::QUEUE_MAIN);slot->full->submit=slot->coarse->submit=slot->submit;throw;}slot->submit=e.context->device.latest_queue_submit_index(daxa::QUEUE_MAIN);slot->full->submit=slot->coarse->submit=slot->submit;return {DaxaFrame(impl_,slot->full),DaxaFrame(impl_,slot->coarse)};}throw std::runtime_error("dual producer backpressure");}
size_t DaxaDualPreprocess::collect(){auto& e=*impl_;e.check_thread();return e.collect_at(e.context->device.oldest_pending_submit_index());}
std::shared_ptr<DaxaFoundation> DaxaDualPreprocess::context()const{return impl_->context;}
DaxaPreprocessReadback DaxaDualPreprocess::readback(const DaxaFrame& frame)const{auto& e=*impl_;e.check_thread();frame.validate();require(frame.owner_.get()==impl_.get(),"foreign dual frame");frame.wait();auto& d=e.context->device;DaxaPreprocessReadback out;for(unsigned p=0;p<8;++p){auto view=frame.plane(DaxaPreprocessPlane(p));size_t bytes=view.size_bytes();daxa::BufferInfo info{.size=bytes,.name="dual diagnostic readback"};auto mem=d.create_memory({.requirements=e.context->coherent_readback_requirements(info),.flags=daxa::MemoryFlagBits::HOST_ACCESS_RANDOM});auto host=d.create_buffer_from_memory_block({.buffer_info=info,.memory_block=mem});struct Cleanup{daxa::Device& d;daxa::BufferId b;~Cleanup(){d.destroy_buffer(b);d.collect_garbage();}} cleanup{d,host};auto r=d.create_command_recorder({.name="dual diagnostic copy"});r.pipeline_barrier({.src_access=daxa::AccessConsts::COMPUTE_SHADER_WRITE,.dst_access=daxa::AccessConsts::TRANSFER_READ});r.copy_buffer_to_buffer({.src_buffer=view.buffer(),.dst_buffer=host,.size=bytes});r.pipeline_barrier({.src_access=daxa::AccessConsts::TRANSFER_WRITE,.dst_access=daxa::AccessConsts::HOST_READ});auto cmd=r.complete_current_commands();d.submit_commands({.command_lists={&cmd,1}});d.wait_idle();out.planes[p].resize(bytes/4);std::memcpy(out.planes[p].data(),d.buffer_host_address(host).value(),bytes);}return out;}
}
